"""Unpack the exact reviewed CITYHILL source/test bundle; no network access."""
from pathlib import Path
import base64,zlib,json,hashlib
ROOT=Path(__file__).resolve().parents[1]
DATA=""""""
payload=zlib.decompress(base64.b64decode(DATA))
assert hashlib.sha256(payload).hexdigest()=="53e6d8f74d6747e404c6db46da8dfed3be2b4a6ff4174165960cfb22a45849c3"
